def predict(board, action):
    mouse_row, mouse_col = action[1], action[2]
    mouse_char = board[mouse_row][mouse_col]

    if mouse_char == 'W':
        board[mouse_row][mouse_col] = 'G'
    else:
        return board  # No change if not 'W'

    # Find all 'G' cells and change them to 'W'
    for r in range(64):
        for c in range(64):
            if board[r][c] == 'G':
                board[r][c] = 'W'

    # Find all 'W' cells and change them to 'G'
    for r in range(64):
        for c in range(64):
            if board[r][c] == 'W':
                board[r][c] = 'G'

    return board
